-- NovaCart application data model — PostgreSQL 16+
-- Schema design only: review migrations and business rules before production use.
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('CUSTOMER','SUPPORT','CATALOG_MANAGER','OWNER');
CREATE TYPE order_status AS ENUM ('PENDING_PAYMENT','CONFIRMED','PACKING','SHIPPED','DELIVERED','CANCELLED','RETURN_REQUESTED','RETURNED');
CREATE TYPE payment_status AS ENUM ('PENDING','AUTHORIZED','PAID','FAILED','REFUNDED','PARTIALLY_REFUNDED');
CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL, password_hash text NOT NULL, name text NOT NULL, role user_role NOT NULL DEFAULT 'CUSTOMER', email_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE UNIQUE INDEX users_email_unique ON users (lower(email)) WHERE deleted_at IS NULL;
CREATE TABLE addresses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, recipient text NOT NULL, phone text NOT NULL, line1 text NOT NULL, line2 text, city text NOT NULL, state text NOT NULL, pincode varchar(6) NOT NULL CHECK (pincode ~ '^[0-9]{6}$'), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, name text NOT NULL, parent_id uuid REFERENCES categories(id));
CREATE TABLE products (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), category_id uuid REFERENCES categories(id), slug text UNIQUE NOT NULL, title text NOT NULL, description text NOT NULL DEFAULT '', active boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX products_category_active_idx ON products(category_id,active);
CREATE TABLE variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, sku text UNIQUE NOT NULL, attributes jsonb NOT NULL DEFAULT '{}'::jsonb, price_paise bigint NOT NULL CHECK(price_paise >= 0), compare_at_paise bigint CHECK(compare_at_paise >= 0), stock_on_hand integer NOT NULL DEFAULT 0 CHECK(stock_on_hand >= 0), stock_reserved integer NOT NULL DEFAULT 0 CHECK(stock_reserved >= 0 AND stock_reserved <= stock_on_hand), active boolean NOT NULL DEFAULT true);
CREATE INDEX variants_product_idx ON variants(product_id);
CREATE TABLE product_images (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, storage_key text NOT NULL, alt_text text NOT NULL, sort_order integer NOT NULL DEFAULT 0);
CREATE TABLE carts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid UNIQUE REFERENCES users(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cart_items (cart_id uuid NOT NULL REFERENCES carts(id) ON DELETE CASCADE, variant_id uuid NOT NULL REFERENCES variants(id), quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 99), PRIMARY KEY(cart_id,variant_id));
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_number text UNIQUE NOT NULL, user_id uuid REFERENCES users(id), status order_status NOT NULL DEFAULT 'PENDING_PAYMENT', payment_status payment_status NOT NULL DEFAULT 'PENDING', currency char(3) NOT NULL DEFAULT 'INR' CHECK(currency='INR'), subtotal_paise bigint NOT NULL CHECK(subtotal_paise >= 0), discount_paise bigint NOT NULL DEFAULT 0 CHECK(discount_paise >= 0), shipping_paise bigint NOT NULL DEFAULT 0 CHECK(shipping_paise >= 0), tax_paise bigint NOT NULL DEFAULT 0 CHECK(tax_paise >= 0), total_paise bigint NOT NULL CHECK(total_paise >= 0), shipping_address jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX orders_user_created_idx ON orders(user_id,created_at DESC);
CREATE TABLE order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id) ON DELETE CASCADE, variant_id uuid REFERENCES variants(id), sku_snapshot text NOT NULL, title_snapshot text NOT NULL, unit_price_paise bigint NOT NULL CHECK(unit_price_paise >= 0), quantity integer NOT NULL CHECK(quantity > 0), line_total_paise bigint NOT NULL CHECK(line_total_paise >= 0));
CREATE TABLE inventory_reservations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), variant_id uuid NOT NULL REFERENCES variants(id), quantity integer NOT NULL CHECK(quantity > 0), expires_at timestamptz NOT NULL, released_at timestamptz, UNIQUE(order_id,variant_id));
CREATE TABLE payment_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), provider text NOT NULL, provider_payment_id text, idempotency_key text NOT NULL UNIQUE, amount_paise bigint NOT NULL CHECK(amount_paise >= 0), status payment_status NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(provider,provider_payment_id));
CREATE TABLE payment_webhook_events (provider text NOT NULL, event_id text NOT NULL, received_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, PRIMARY KEY(provider,event_id));
CREATE TABLE shipments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_id uuid NOT NULL REFERENCES orders(id), provider text, tracking_number text, status text NOT NULL DEFAULT 'PENDING', shipped_at timestamptz, delivered_at timestamptz);
CREATE TABLE returns (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), order_item_id uuid NOT NULL REFERENCES order_items(id), quantity integer NOT NULL CHECK(quantity > 0), reason text NOT NULL, status text NOT NULL DEFAULT 'REQUESTED', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_attempt_id uuid NOT NULL REFERENCES payment_attempts(id), return_id uuid REFERENCES returns(id), amount_paise bigint NOT NULL CHECK(amount_paise > 0), provider_refund_id text UNIQUE, idempotency_key text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'PENDING');
CREATE TABLE wishlists (user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, product_id uuid NOT NULL REFERENCES products(id) ON DELETE CASCADE, PRIMARY KEY(user_id,product_id));
CREATE TABLE reviews (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), product_id uuid NOT NULL REFERENCES products(id), user_id uuid NOT NULL REFERENCES users(id), rating smallint NOT NULL CHECK(rating BETWEEN 1 AND 5), body text NOT NULL, moderation_status text NOT NULL DEFAULT 'PENDING', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE coupons (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text UNIQUE NOT NULL, type text NOT NULL CHECK(type IN ('PERCENT','FIXED')), value integer NOT NULL CHECK(value > 0), starts_at timestamptz, ends_at timestamptz, usage_limit integer, usage_count integer NOT NULL DEFAULT 0);
CREATE TABLE support_tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id), order_id uuid REFERENCES orders(id), subject text NOT NULL, status text NOT NULL DEFAULT 'OPEN', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, entity_type text NOT NULL, entity_id text, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX audit_events_created_idx ON audit_events(created_at DESC);
-- TODO: implement transaction-safe reservation logic, webhook verification, retention and RBAC in backend.
